// vm — a register-machine bytecode interpreter: the core loop every VM / DSL / calculator
// runs (fetch → decode → dispatch → execute over a register file). A deterministic instruction
// stream is generated by the shared LCG and executed in order; the final register state reduces
// to a checksum. A real interpreter workload — dispatch-heavy, not a teaching algorithm — and
// byte-identical across every language.
package main

import (
	"fmt"
	"os"
	"strconv"
)

const MOD int64 = 1000000007
const NREG = 8

func main() {
	if len(os.Args) < 2 {
		fmt.Fprintln(os.Stderr, "usage: vm <n>")
		os.Exit(1)
	}
	n, _ := strconv.ParseInt(os.Args[1], 10, 64)
	seed := int64(42)
	var regs [NREG]int64
	for i := 0; i < NREG; i++ { // seed the register file
		regs[i] = int64(i) + 1
	}
	for k := int64(0); k < n; k++ {
		seed = (seed*1103515245 + 12345) % 2147483648 // fetch
		instr := (seed >> 8) & 0x7fffff               // decode
		op := instr % 8
		dst := (instr / 8) % NREG
		a := (instr / 64) % NREG
		imm := (instr / 512) % 251
		switch op { // dispatch → execute
		case 0:
			regs[dst] = imm // LOADI
		case 1:
			regs[dst] = (regs[dst] + regs[a]) % MOD // ADD
		case 2:
			regs[dst] = (regs[dst] + MOD - regs[a]) % MOD // SUB
		case 3:
			regs[dst] = (regs[dst]*regs[a] + 1) % MOD // MULADD
		case 4:
			regs[dst] = (regs[dst] + imm) % MOD // ADDI
		case 5:
			regs[dst] = (regs[dst] * (imm + 1)) % MOD // MULI
		case 6:
			regs[dst] = regs[a] // MOV
		case 7:
			regs[dst] = (regs[dst] + regs[a] + imm) % MOD // MIX
		}
	}
	var checksum int64 = 0
	for i := 0; i < NREG; i++ {
		checksum = (checksum*31 + regs[i]) & 268435455
	}
	fmt.Printf("%d\n", checksum)
}
